import * as THREE from 'three/webgpu';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  const timelines = [];
  const disposables = [];

  // Colors from spec
  const colors = {
    background: new THREE.Color('#0b0b10'),
    surface: new THREE.Color('#14141a'),
    ink: new THREE.Color('#16161d'),
    paper: new THREE.Color('#e8ecf2'),
    accent: new THREE.Color('#ff2a38'),
  };

  // Helper: Create DataTexture from gradient stops
  function createGradientTexture(stops, width = 1, height = 256) {
    const data = new Uint8Array(width * height * 4);

    for (let y = 0; y < height; y++) {
      const t = y / (height - 1);

      let s1 = stops[0];
      let s2 = stops[stops.length - 1];
      for (let i = 0; i < stops.length - 1; i++) {
        if (t >= stops[i].at && t <= stops[i + 1].at) {
          s1 = stops[i];
          s2 = stops[i + 1];
          break;
        }
      }

      const range = s2.at - s1.at;
      const localT = range > 0 ? (t - s1.at) / range : 0;

      const c1 = new THREE.Color(s1.hex);
      const c2 = new THREE.Color(s2.hex);
      const c = c1.clone().lerp(c2, localT);

      for (let x = 0; x < width; x++) {
        const idx = (y * width + x) * 4;
        data[idx] = Math.round(c.r * 255);
        data[idx + 1] = Math.round(c.g * 255);
        data[idx + 2] = Math.round(c.b * 255);
        data[idx + 3] = 255;
      }
    }

    const tex = new THREE.DataTexture(data, width, height, THREE.RGBAFormat);
    tex.magFilter = THREE.LinearFilter;
    tex.minFilter = THREE.LinearFilter;
    tex.needsUpdate = true;
    return tex;
  }

  // Helper: Create radial gradient for shadow
  function createRadialGradientTexture(size = 256) {
    const data = new Uint8Array(size * size * 4);
    const center = size / 2;
    const maxDist = Math.sqrt(2) * center;

    for (let y = 0; y < size; y++) {
      for (let x = 0; x < size; x++) {
        const dx = x - center;
        const dy = y - center;
        const dist = Math.sqrt(dx * dx + dy * dy);
        const t = Math.min(1, dist / maxDist);
        const alpha = Math.round((1 - t) * 0.6 * 255);

        const idx = (y * size + x) * 4;
        data[idx] = 0;
        data[idx + 1] = 0;
        data[idx + 2] = 0;
        data[idx + 3] = alpha;
      }
    }

    const tex = new THREE.DataTexture(data, size, size, THREE.RGBAFormat);
    tex.magFilter = THREE.LinearFilter;
    tex.minFilter = THREE.LinearFilter;
    tex.needsUpdate = true;
    return tex;
  }

  // Helper: Create scratch noise normal map
  function createScratchNormalMap(size = 256) {
    const data = new Uint8Array(size * size * 4);

    for (let i = 0; i < size * size; i++) {
      const val = Math.random() * 0.3 + 0.6;
      const idx = i * 4;
      data[idx] = Math.round(val * 255);
      data[idx + 1] = Math.round(val * 255);
      data[idx + 2] = Math.round(val * 255);
      data[idx + 3] = 255;
    }

    const tex = new THREE.DataTexture(data, size, size, THREE.RGBAFormat);
    tex.wrapS = THREE.RepeatWrapping;
    tex.wrapT = THREE.RepeatWrapping;
    tex.repeat.set(4, 4);
    tex.magFilter = THREE.LinearFilter;
    tex.minFilter = THREE.LinearMipMapLinearFilter;
    tex.needsUpdate = true;
    return tex;
  }

  // BACKDROP PLANE (7 x 6 at z = -3)
  const backdropGradientStops = [
    { at: 0, hex: '#0b0b10' },
    { at: 0.7, hex: '#101017' },
    { at: 1, hex: '#16161d' },
  ];
  const backdropGeo = new THREE.PlaneGeometry(7, 6);
  const backdropGradientTex = createGradientTexture(backdropGradientStops, 1, 512);
  const backdropMat = new THREE.MeshBasicMaterial({ map: backdropGradientTex });
  const backdrop = new THREE.Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -3;
  group.add(backdrop);
  disposables.push(backdropGeo, backdropMat, backdropGradientTex);

  // CONTACT SHADOW (radial gradient plane at y = -0.36)
  const shadowGeo = new THREE.CircleGeometry(1.5, 64);
  const shadowTex = createRadialGradientTexture(256);
  const shadowMat = new THREE.MeshBasicMaterial({
    map: shadowTex,
    transparent: true,
    side: THREE.DoubleSide,
  });
  const shadow = new THREE.Mesh(shadowGeo, shadowMat);
  shadow.position.y = -0.36;
  shadow.rotation.x = -Math.PI / 2;
  group.add(shadow);
  disposables.push(shadowGeo, shadowMat, shadowTex);

  // PEDESTAL (cylinder, radius 1.1, height 0.5, top at y = -0.35)
  const pedestalGeo = new THREE.CylinderGeometry(1.1, 1.1, 0.5, 64);
  const pedestalMat = new THREE.MeshStandardMaterial({
    color: colors.surface,
    roughness: 0.7,
    metalness: 0.35,
  });
  const pedestal = new THREE.Mesh(pedestalGeo, pedestalMat);
  pedestal.position.y = -0.6;
  group.add(pedestal);
  disposables.push(pedestalGeo, pedestalMat);

  // TORUS KNOT (radius 0.7, tube 0.22, 220 x 36 segments at [0, 0.4, 0])
  const torusKnotGeo = new THREE.TorusKnotGeometry(0.7, 0.22, 220, 36);

  const roughnessMap = ctx.textureLoader.load('/prism-assets/chrome/brushed-metal.map.png');
  disposables.push(roughnessMap);

  const noiseTex = createScratchNormalMap(256);
  disposables.push(noiseTex);

  const torusKnotMat = new THREE.MeshPhysicalMaterial({
    color: colors.ink,
    roughness: 0.55,
    metalness: 0.55,
    clearcoat: 0.22,
    clearcoatRoughness: 0.35,
    roughnessMap: roughnessMap,
    normalMap: noiseTex,
    normalScale: new THREE.Vector2(0.15, 0.15),
  });

  if (torusKnotMat.anisotropy !== undefined) {
    torusKnotMat.anisotropy = 0.9;
  }

  const torusKnot = new THREE.Mesh(torusKnotGeo, torusKnotMat);
  torusKnot.position.set(0, 0.4, 0);
  group.add(torusKnot);
  disposables.push(torusKnotGeo, torusKnotMat);

  // LIGHTING
  const ambientLight = new THREE.AmbientLight(0xffffff, 0.5);
  group.add(ambientLight);

  const directionalLight = new THREE.DirectionalLight(0xffffff, 0.8);
  directionalLight.position.set(2, 2, 2);
  group.add(directionalLight);

  // TEXT CONTENT (via fontAtlas)
  if (ctx.fontAtlas && ctx.fontAtlas.createText) {
    const headlineText = ctx.fontAtlas.createText('Material study 03', {
      family: 'Lora',
      fontSize: 68,
      fontWeight: 600,
      letterSpacing: -0.005,
      lineHeight: 1.1,
      color: colors.paper,
    });
    if (headlineText) {
      headlineText.position.set(0, -1.2, 0.5);
      group.add(headlineText);
    }

    const captionText = ctx.fontAtlas.createText('GRADE 5 TITANIUM / BRUSHED AT 1200 GRIT', {
      family: 'JetBrains Mono',
      fontSize: 18,
      fontWeight: 400,
      letterSpacing: 0.08,
      lineHeight: 1.4,
      color: colors.accent,
    });
    if (captionText) {
      captionText.position.set(0, -1.6, 0.5);
      group.add(captionText);
    }
  }

  // APPLY CINEMATIC PRIMITIVES
  if (ctx.primitives && ctx.primitives.orbit) {
    const result = ctx.primitives.orbit(torusKnot, {
      speed: 0.1,
      radius: 0.4,
    });
    if (result && result.kill) {
      timelines.push(result);
    }
  }

  // HANDLERS
  group.userData.handlers = {};

  // CLEANUP
  group.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    disposables.forEach(d => {
      if (d.dispose) d.dispose();
    });
  };

  return group;
}
